public sealed class Tuple2UintegerJsonConverter : JsonConverter<Tuple2Uinteger>
{
    public override Tuple2Uinteger Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType != JsonTokenType.StartArray)
        {
            throw new JsonException("expected a two-element array, got " + reader.TokenType.ToString());
        }
        reader.Read();
        var item1 = reader.GetUInt32();
        reader.Read();
        var item2 = reader.GetUInt32();
        reader.Read();
        if (reader.TokenType != JsonTokenType.EndArray)
        {
            throw new JsonException("expected a two-element array");
        }
        return new Tuple2Uinteger(item1, item2);
    }

    public override void Write(Utf8JsonWriter writer, Tuple2Uinteger value, JsonSerializerOptions options)
    {
        writer.WriteStartArray();
        writer.WriteNumberValue(value.Item1);
        writer.WriteNumberValue(value.Item2);
        writer.WriteEndArray();
    }
}

